import xml.etree.ElementTree as ET
import logging
import xmlschema

logging.basicConfig(level=logging.INFO)

schema = xmlschema.XMLSchema('schema.xsd')

def parse_xml(xml_string):
    try:
        if not schema.is_valid(xml_string):
            logging.error("XML input does not conform to the specified schema.")
            return "Invalid XML input."

        parser = ET.XMLParser()
        root = ET.fromstring(xml_string, parser=parser)

        allowed_tags = {"tag1", "tag2"}
        allowed_attributes = {"attr1", "attr2"}

        for elem in root.iter():
            if elem.tag not in allowed_tags:
                logging.error(f"Disallowed tag: {elem.tag}")
                return "Invalid XML input."
            for attribute in list(elem.attrib):
                if attribute not in allowed_attributes:
                    logging.error(f"Disallowed attribute: {attribute} in tag: {elem.tag}")
                    del elem.attrib[attribute]

        logging.info("XML input validated successfully.")
        return root

    except ET.ParseError as e:
        logging.error(f"Parse error: {str(e)}")
        return "There was an error processing your XML input."
    except Exception as e:
        logging.error(f"Unexpected error: {str(e)}")
        # Notify system administrator about the exception
        return "An internal error occurred."

