        return jsonify({"error": "Disallowed file extension"}), 400

    file_path = os.path.join("/var/www/images/", filename)
    absolute_path = os.path.abspath(file_path)

    if not any(absolute_path.startswith(os.path.abspath(path)) for path in allowed_paths):
        return jsonify({"error": "Unauthorized access to file"}), 403

    try:
        os.remove(absolute_path)
        return jsonify({"message": "File deleted successfully"}), 200
    except FileNotFoundError:
        return jsonify({"error": "404 Not Found"}), 404
    except PermissionError:
        return jsonify({"error": "403 Forbidden"}), 403
