import tarfile
import os

def extract_tar(file_name):
    allowed_extensions = ['.tar', '.tar.gz']
    safe_directory = '/tmp/'

    if not any(file_name.endswith(ext) for ext in allowed_extensions):
        return "Error: File extension not allowed."

    try:
        with tarfile.open(file_name) as tar:
            for entry in tar:
                extracted_path = os.path.join(safe_directory, entry.name)
                if os.path.abspath(extracted_path).startswith(os.path.abspath(safe_directory)):
                    tar.extract(entry, safe_directory)
                else:
                    return "Error: Attempted path traversal detected."
    except FileNotFoundError:
        return "Error: File not found."
    except tarfile.TarError as e:
        # Log error (not implemented here)
        return "Error: Tar file extraction failed."
    except PermissionError:
        return "Error: Permission denied during extraction."

