from flask import request, Flask, jsonify
import ldap3

app = Flask(__name__)

@app.route("/normal")
def normal():
    try:
        dc = request.args.get('dc')
        username = request.args.get('username')

        # Validate input parameters
        if not (username.isalnum() and dc in ["example.com", "example.org"]):
            raise ValueError("Invalid input parameters")

        # Escape special characters
        escaped_username = ldap3.utils.filter.escape_filter_chars(username)
        escaped_dc = ldap3.utils.filter.escape_filter_chars(dc)

        server = ldap3.Server('localhost')
        conn = ldap3.Connection(server)

        # Establish LDAP connection
        if not conn.bind():
            return jsonify({"error": "Failed to connect to LDAP"}), 500

        # Perform the LDAP search
        search_filter = f"(&(objectClass=person)(uid={escaped_username}))"
        conn.search(escaped_dc, search_filter)

        if conn.entries:
            return jsonify(conn.entries), 200
        else:
            return jsonify({"error": "User not found"}), 404

    except ldap3.LDAPException as e:
        return jsonify({"error": str(e)}), 500
    except ValueError as ve:
        return jsonify({"error": str(ve)}), 400

if __name__ == "__main__":
    app.run(debug=True)

