import os
import re
import logging

def raisePrivileges():
    os.setuid(0)  # Assume this elevates the privileges appropriately

def lowerPrivileges():
    os.setuid(1000)  # Assume this returns to normal user privileges

def makeNewUserDir(username):
    pattern = r'^[a-zA-Z0-9_]{1,32}$'
    if not re.match(pattern, username):
        raise ValueError("Invalid username format.")

    raisePrivileges()

    directory_path = f"/home/{username}"

    try:
        if not os.path.exists(directory_path):
            os.makedirs(directory_path)
            os.chmod(directory_path, 0o700)  # Secure the directory
    except FileExistsError:
        logging.error("Directory already exists, not creating again.")
    finally:
        lowerPrivileges()

