def verifyJWTToken(jwt_token):
    try:
        # Get unverified claims
        claims = jwt.get_unverified_claims(jwt_token)

        # Check algorithm
        if claims['alg'] not in ["HS256", "RS256"]:
            raise InvalidTokenError("Non-allowed algorithm")

        # Verify the token
        decoded_token = jwt.decode(jwt_token, key='your_secret_key_here', algorithms=["HS256", "RS256"])

        # Check expiration
        exp = claims.get('exp')
        if exp is None or datetime.utcfromtimestamp(exp) < datetime.utcnow():
            raise ExpiredSignatureError("Token expired")

        # Validate issuer and audience
        if claims.get('iss') != "trusted_issuer" or claims.get('aud') != "trusted_audience":
            raise InvalidTokenError("Invalid issuer or audience")

        return decoded_token

    except InvalidTokenError:
        return "Unauthorized response"
    except ExpiredSignatureError:
        return "Token expired response"
    except DecodeError:
        return "Malformed token response"

