    if is_account_locked(username):
        return 'Authentication failed'

    typed_pw_normalized = normalize_password(typed_pw)
    actual_pw_hash = bcrypt.hashpw(normalize_password(actual_pw).encode(), bcrypt.gensalt())

    if not hmac.compare_digest(actual_pw_hash, bcrypt.hashpw(typed_pw_normalized.encode(), bcrypt.gensalt())):
        log_failed_attempt(username)
        raise AuthenticationError('Authentication failed')

    return 'Password is valid'

