from socket import socket, bind, listen, accept, recv, send, close

def echoServer(port):
    server_socket = socket()
    try:
        bind(server_socket, ('', port))
        listen(5)
        while True:
            client_socket, addr = accept(server_socket)
            try:
                data = recv(client_socket, 1024)
                if len(data) > 1024:
                    send(client_socket, b"Error: Input size exceeds maximum limit.")
                else:
                    command = data.decode('utf-8').strip()
                    if command == "CLOSE":
                        send(client_socket, b"Connection closing.")
                        close(client_socket)
                        break
                    elif command == "ECHO":
                        send(client_socket, data)
                    else:
                        send(client_socket, b"Error: Invalid command.")
            except ValueError:
                send(client_socket, b"Error: Invalid value received.")
                close(client_socket)
            except BufferError:
                send(client_socket, b"Error: Buffer error.")
                close(client_socket)
    except ConnectionError:
        close(server_socket)

