from django.http import HttpResponse

def xpath_query(request):
    xpath = request.GET.get('xpath', '')
    xml = request.GET.get('xml', '')

    if len(xml) > 1 * 1024 * 1024: 
        return HttpResponse("400 Bad Request: XML size exceeds limit.", status=400)

    try:
        etree.fromstring(xml)
    except etree.XMLSyntaxError:
        return HttpResponse("400 Bad Request: Invalid XML provided.", status=400)

    if not xpath.startswith('/tag[@id='):
        return HttpResponse("400 Bad Request: Invalid XPath provided.", status=400)

    parsed_xml = etree.fromstring(xml)
    try:
        xpath_query = etree.XPath(xpath)
        results = xpath_query(parsed_xml)
    except etree.XPathEvalError:
        return HttpResponse("400 Bad Request: XPath evaluation error.", status=400)

    return HttpResponse(str(results))

