app = Flask(__name__)
login_manager = LoginManager(app)
DYNAMO_CLIENT = boto3.client('dynamodb')
rate_limit = defaultdict(lambda: {'attempts': 0, 'last_attempt': 0})
LOGIN_ATTEMPT_LIMIT = 5
LOGIN_TIME_FRAME = 60  # seconds
SESSION_TIMEOUT = 1800  # seconds

class User(UserMixin):
    def __init__(self, username):
        self.username = username

def validate_input(username, password):
    if not (username.isalnum() and password.isalnum()):
        raise ValueError("Invalid credentials")
    if len(username) > 20 or len(password) > 20:
        raise ValueError("Invalid credentials")

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def is_rate_limited(ip):
    current_time = time()
    if rate_limit[ip]['last_attempt'] == 0:
        rate_limit[ip]['last_attempt'] = current_time
    if current_time - rate_limit[ip]['last_attempt'] > LOGIN_TIME_FRAME:
        rate_limit[ip]['attempts'] = 0
        rate_limit[ip]['last_attempt'] = current_time

    if rate_limit[ip]['attempts'] >= LOGIN_ATTEMPT_LIMIT:
        return True
    return False

def getUser(username, password):
    try:
        validate_input(username, password)
        ip = request.remote_addr

        if is_rate_limited(ip):
            return "Too many login attempts, please try again later."

        hashed_password = hash_password(password)
        response = DYNAMO_CLIENT.get_item(
            TableName='users',
            Key={'username': {'S': username}}
        )
        user_data = response['Item']
        if user_data['password']['S'] != hashed_password:
            rate_limit[ip]['attempts'] += 1
            return "Invalid credentials"

        user = User(username)
        login_user(user)
        return "Login successful"
    except KeyError:
        return "User not found"
    except ValueError:
        return "Invalid credentials"

@login_manager.user_loader
def load_user(username):
    return User(username)

@app.route('/auth', methods=['POST'])
def auth_user():
    username = request.json.get('username')
    password = request.json.get('password')
    return getUser(username, password)

@app.before_request
def before_request():
    if current_user.is_authenticated and (time() - current_user.last_login > SESSION_TIMEOUT):
        logout_user()
